(function(E){ const x = E["hr-m1"] = E["hr-m1"] || {units:{}}; x.units["hr-1-3"] = {"explain":{"id":"c-hr-1-3-e","course":"hr","unit":"hr-1-3","type":"explain","level":"B1","title":{"en":"Calls and video meetings","tr":"Telefon ve görüntülü görüşmeler","fa":"تماس تلفنی و جلسه‌ی تصویری"},"objective":{"en":"After this lesson, you can check and clarify on a call: ask someone to repeat, spell names and confirm numbers and dates.","tr":"Bu dersin sonunda bir telefon görüşmesinde tekrar isteyebilecek, isimleri harf harf söyletebilecek, sayıları ve tarihleri teyit edebileceksin.","fa":"بعد از این درس می‌توانی در تماس تلفنی جزئیات را چک کنی: بخواهی تکرار کنند، اسم‌ها را هجی کنند و عددها و تاریخ‌ها را تأیید کنی."},"hook":{"en":"On a call, ask, then repeat what you heard. One wrong number can cost you an interview. On the phone there is no face to read. So you check, out loud, and nobody minds.","tr":"Telefonda sor, sonra duyduğunu tekrar et. Tek bir yanlış numara sana bir mülakata mal olabilir. Telefonda okunacak bir yüz yok. O yüzden yüksek sesle teyit edersin ve kimse buna alınmaz.","fa":"پشت تلفن بپرس و بعد چیزی را که شنیدی تکرار کن. یک شماره‌ی اشتباه ممکن است باعث شود یک مصاحبه را از دست بدهی. پشت تلفن چهره‌ای نمی‌بینی. پس با صدای بلند چک می‌کنی و کسی هم ناراحت نمی‌شود."},"before":{"en":"After a call, confirm a name, a phone number and a date in a short message.","tr":"Bir telefon görüşmesinden sonra kısa bir mesajla bir adı, bir telefon numarasını ve bir tarihi teyit et.","fa":"بعد از یک تماس، در یک پیام کوتاه یک اسم، یک شماره تلفن و یک تاریخ را تأیید کن."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"5"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"4"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Ask, then repeat what you heard","tr":"Sor, sonra duyduğunu tekrar et","fa":"بپرس و بعد چیزی را که شنیدی تکرار کن"},"body":{"en":"A wrong name or number on a call can become a wrong email or a missed interview. Guessing is the real mistake. So ask, then repeat the details.","tr":"Telefonda yanlış anlaşılan bir ad ya da numara, yanlış bir e-postaya ya da kaçan bir mülakata dönüşebilir. Asıl hata tahmin etmektir. Bu yüzden sor, sonra bilgileri tekrar et.","fa":"اسم یا شماره‌ای که پشت تلفن اشتباه بشنوی، ممکن است به ایمیل اشتباه یا از دست رفتن مصاحبه ختم شود. اشتباه اصلی حدس زدن است. پس بپرس و بعد جزئیات را تکرار کن."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Checking and clarifying questions","tr":"Teyit ve açıklama soruları","fa":"سؤال‌های تأیید و روشن‌سازی"},"steps":[{"en":"Check a word: did + bare verb, never said.","tr":"Bir kelimeyi kontrol et: did + yalın fiil, said asla.","fa":"برای چک کردن یک کلمه، بعد از did شکل ساده‌ی فعل می‌آید، هرگز said.","ex":"Sorry, did you say fifteen or fifty?"},{"en":"Check spelling with do + you + spell.","tr":"Yazılışı do + you + spell ile sor.","fa":"برای هجی از do you spell استفاده کن.","ex":"How do you spell your surname?"},{"en":"Check everything: read it back.","tr":"Hepsini kontrol et: geri oku.","fa":"همه را چک کن: دوباره برایش بخوان.","ex":"Let me check I've got that: ..."},{"en":"Say numbers in pairs and dates with the month, so nothing is misheard.","tr":"Sayıları ikişer ikişer, tarihleri ayıyla söyle ki yanlış duyulmasın.","fa":"عددها را دوتایی و تاریخ را با ماه بگو تا اشتباه شنیده نشود.","ex":"one-five, one-five; the third of March"}],"table":{"headers":{"en":["Need","Say"],"tr":["İhtiyaç","Söyle"],"fa":["چه می‌خواهی؟","چه بگویی"]},"rows":[["Hear again","Sorry, could you repeat that?"],["Spelling","How do you spell that? / Could you spell it, please?"],["Check a number","Did you say fifteen or fifty?"],["Confirm","Let me check I've got that."]]},"tip":{"en":"Turkish asks with the particle mi and Persian with intonation or 'aya', so the verb never changes. English moves did or do to the front and strips the main verb.","tr":"Türkçede soru 'mi' ekiyle yapılır ve fiil değişmez: 'On beş mi dedin?'. İngilizcede did ya da do başa gelir ve asıl fiil yalın kalır: Did you say...?","fa":"در فارسی سؤال را با لحن یا «آیا» می‌سازیم و فعل عوض نمی‌شود: «گفتی پونزده؟». در انگلیسی did یا do اول جمله می‌آید و فعل اصلی ساده می‌شود: «⁨Did you say...?⁩»"},"wrong":"Sorry, did you said fifteen?","right":"Sorry, did you say fifteen?"},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"Sorry, could you repeat that?","meaning":{"en":"Asks for a repeat politely.","tr":"Kibarca tekrar ister.","fa":"مؤدبانه تکرار را درخواست می‌کند."}},{"phrase":"Did you say fifteen or fifty?","meaning":{"en":"Checks two similar numbers.","tr":"İki benzer sayıyı kontrol eder.","fa":"دو عددِ شبیه به هم را چک می‌کند."}},{"phrase":"Let me check I've got that.","meaning":{"en":"Introduces a read-back.","tr":"Geri okumayı başlatır.","fa":"بازخوانی اطلاعات را شروع می‌کند."}},{"phrase":"spell","meaning":{"en":"To say the letters of a word one by one.","tr":"hecelemek.","fa":"هجی کردن"}},{"phrase":"the line is breaking up","meaning":{"en":"The sound keeps cutting off.","tr":"hat kesiliyor.","fa":"صدا قطع و وصل می‌شود؛ خط خوب نیست"}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Asking again is professional","tr":"Tekrar sormak profesyonelliktir","fa":"دوباره پرسیدن یعنی حرفه‌ای بودن"},"body":{"en":"Asking someone to repeat or spell is normal and professional on international calls. It shows care, not weakness. Many native speakers also ask for repeats on bad lines.","tr":"Uluslararası görüşmelerde tekrar ya da hecelemek istemek normal ve profesyoneldir. Zayıflık değil, özen göstergesidir. Ana dili İngilizce olanlar da kötü hatlarda tekrar ister.","fa":"در تماس‌های بین‌المللی، اینکه از کسی بخواهی حرفش را تکرار یا اسمش را هجی کند، کاملاً عادی و حرفه‌ای است. این کار نشانه‌ی دقت است، نه ضعف زبان. خود انگلیسی‌زبان‌ها هم وقتی خط بد است دوباره می‌پرسند."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از حدس زدن تا پرسیدن و تکرار کردن"},"text":"Facts: You didn't hear the number clearly. The date is Tuesday the 14th at ten.","item":"Okay, great, thanks. See you on the day.","why":{"en":"Weak: you didn't hear it, but you say yes. Strong: you check the number and repeat the date.","tr":"Zayıf: duymadın ama evet diyorsun. Güçlü: sayıyı soruyor, tarihi tekrar ediyorsun.","fa":"در نسخه‌ی اول نشنیده‌ای، ولی می‌گویی باشد. در نسخه‌ی دوم عدد را می‌پرسی و تاریخ را تکرار می‌کنی."},"answer":"Sorry, was that 14 or 40? Let me check I've got that: Tuesday the 14th at ten.","cut":["Okay, great, thanks.","on the day"],"cutHint":{"en":"Tap the words that check nothing and give no date.","tr":"Hiçbir şeyi kontrol etmeyen ve tarih vermeyen sözlere dokun.","fa":"روی حرف‌هایی بزن که چیزی را چک نمی‌کنند و تاریخی نمی‌دهند."}},"quick":{"prompt":"A candidate asks you to repeat his surname twice. What does this usually show on an international call?","options":["Care about getting it right","Weak English","Impatience"],"correct":0,"why":{"en":"Care about getting it right: asking someone to repeat or spell is normal and professional on international calls. It shows care, not weakness.","tr":"Doğrusunu bilme özeni: Uluslararası görüşmelerde tekrar etmesini ya da harf harf söylemesini istemek normal ve profesyoneldir. Zayıflığı değil, özeni gösterir.","fa":"نشانه‌ی دقت است: در تماس‌های بین‌المللی اینکه از کسی بخواهی تکرار یا هجی کند عادی و حرفه‌ای است، نه نشانه‌ی ضعف."},"point":4},"remember":{"en":"Does the question start with did or do? Then the next verb has no -s and no -ed. Result of this lesson: you can check names, numbers and dates on a call. You also have a confirmation message.","tr":"Soru did ya da do ile mi başlıyor? O zaman sonraki fiil -s ya da -ed almaz. Bu dersin sonucu: telefonda ad, sayı ve tarihleri kontrol edebilirsin ve elinde bir teyit mesajı olur.","fa":"سؤال با ⁨did⁩ یا ⁨do⁩ شروع شده؟ پس فعل بعدی نه ⁨-s⁩ می‌گیرد و نه ⁨-ed⁩. حالا می‌توانی پشت تلفن اسم، عدد و تاریخ را کنترل کنی. یک پیام تأیید هم آماده است."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Guessing on the phone: must, can't, might","tr":"Telefonda tahmin: must, can't, might","fa":"حدس زدن پشت تلفن: must، can’t، might"},"steps":[{"en":"Almost sure yes: must + verb.","tr":"Neredeyse eminim, evet: must + fiil.","fa":"اگر تقریباً مطمئنی که بله، must و فعل ساده را به کار ببر.","ex":"She must be on another call."},{"en":"Maybe: might or could + verb.","tr":"Belki: might ya da could + fiil.","fa":"اگر فقط احتمال می‌دهی، might یا could و فعل ساده را به کار ببر.","ex":"He might be on the bus."},{"en":"Almost sure no: can't + verb.","tr":"Neredeyse eminim, hayır: can't + fiil.","fa":"اگر تقریباً مطمئنی که نه، can't و فعل ساده را به کار ببر.","ex":"That can't be his number."},{"en":"About the past: add have + past participle.","tr":"Geçmiş için: have + past participle ekle.","fa":"برای حدس درباره‌ی گذشته، have و اسم مفعول را اضافه کن.","ex":"He can't have heard my message."}],"table":{"headers":{"en":["How sure?","Present","Past"],"tr":["Ne kadar emin?","Şimdi","Geçmiş"],"fa":["چقدر مطمئنی؟","حال","گذشته"]},"rows":[["Almost sure: yes","She must be on another call.","He must have left early."],["Maybe","It might be the old number.","She might have sent it already."],["Almost sure: no","That can't be his number.","He can't have heard my message."]]},"body":{"en":"B2 track: when you return the call, use one guess with must, might or can't (for example \"You must be driving, shall I call later?\").","tr":"B2 yolu: geri ararken must, might veya can't ile bir tahmin kullan (örneğin \"You must be driving, shall I call later?\").","fa":"مسیر B2: وقتی دوباره تماس می‌گیری، یک حدس با must، might یا can't بزن (مثلاً «⁨You must be driving, shall I call later?⁩»)."}}},"grammar":{"id":"c-hr-1-3-g","level":"B1","course":"hr","unit":"hr-1-3","title":"Checking and clarifying questions","titleTr":"Teyit ve açıklama soruları","exp":{"en":"On a call you cannot see the other person, so you check. Questions use an auxiliary (do, does, did, can, could) before the subject, and the main verb stays in the base form: \"Did you say fifteen or fifty?\" not \"Did you said...?\" and not \"You said fifteen?\" (that is only a quick confirmation when your voice goes up). Useful chunks: \"Sorry, could you repeat that?\", \"How do you spell your surname?\", \"Could you speak a little slower?\", \"Let me check I've got that: ...\". Say numbers in pairs and dates with the month: \"one-five, one-five, double-nine\"; \"the third of March\".","tr":"Telefonda karşındakini göremezsin, o yüzden teyit edersin. Sorularda yardımcı fiil (do, does, did, can, could) öznenin önüne gelir ve ana fiil yalın kalır: \"Did you say fifteen or fifty?\"; \"Did you said...?\" değil. Türkçedeki gibi sona \"mı\" eklemek yoktur. Faydalı kalıplar: \"Sorry, could you repeat that?\", \"How do you spell your surname?\", \"Could you speak a little slower?\", \"Let me check I've got that: ...\". Sayıları ikişerli, tarihleri ay ile söyle: \"one-five, one-five, double-nine\"; \"the third of March\".","fa":"پشت تلفن طرف مقابل را نمی‌بینی، پس باید مدام مطمئن شوی که درست شنیده‌ای. در سؤال‌های انگلیسی، فعل کمکی (do، does، did، can، could) قبل از فاعل می‌آید و فعل اصلی به شکل ساده باقی می‌ماند: «⁨Did you say fifteen or fifty?⁩» درست است، نه «⁨Did you said...?⁩». جمله‌ی «⁨You said fifteen?⁩» هم فقط وقتی جواب می‌دهد که با لحن بالارونده بپرسی، برای تأیید سریع؛ مثل «گفتید پونزده؟» در فارسی. چند عبارت آماده: «⁨Sorry, could you repeat that?⁩»، «⁨How do you spell your surname?⁩»، «⁨Could you speak a little slower?⁩» و «Let me check I've got that: ...». شماره‌ها را دوتا‌دوتا بگو و تاریخ را همراه با اسم ماه: «one-five, one-five, double-nine» و «the third of March»."},"formsTable":{"headers":{"en":["Need","Say"],"tr":["İhtiyaç","Söyle"],"fa":["چه می‌خواهی؟","چه بگویی"]},"rows":[["Hear again","Sorry, could you repeat that?"],["Spelling","How do you spell that? / Could you spell it, please?"],["Check a number","Did you say fifteen or fifty?"],["Confirm","Let me check I've got that."]]},"wrong":"Did you said fifteen or fifty?","right":"Did you say fifteen or fifty?","blank":{"sentence":"Sorry, did you ___ fifteen or fifty?","word":"say","distractors":["said","saying"]},"wrong2":"How you spell your surname?","right2":"How do you spell your surname?","blank2":{"sentence":"How ___ you spell your surname?","word":"do","distractors":["are","does"]},"expParts":{"tryFrom":"blank","hook":{"en":"On the phone there is no face to read. So you check, out loud, and nobody minds.","tr":"Telefonda okunacak bir yüz yok. O yüzden yüksek sesle teyit edersin ve kimse buna alınmaz.","fa":"پشت تلفن چهره‌ای نمی‌بینی. پس با صدای بلند چک می‌کنی و کسی هم ناراحت نمی‌شود."},"tryWhy":{"en":"say: 'did' already carries the past. The main verb goes back to its base form.","tr":"say: geçmiş zamanı 'did' zaten taşıyor. Asıl fiil yalın hâline döner.","fa":"جواب say است، چون گذشته بودن را خودِ did نشان می‌دهد و فعل اصلی به شکل ساده برمی‌گردد."},"rule":[{"en":"Check a word: did + bare verb, never said.","tr":"Bir kelimeyi kontrol et: did + yalın fiil, said asla.","fa":"برای چک کردن یک کلمه، بعد از did شکل ساده‌ی فعل می‌آید، هرگز said.","ex":"Sorry, did you say fifteen or fifty?"},{"en":"Check spelling with do + you + spell.","tr":"Yazılışı do + you + spell ile sor.","fa":"برای هجی از do you spell استفاده کن.","ex":"How do you spell your surname?"},{"en":"Check everything: read it back.","tr":"Hepsini kontrol et: geri oku.","fa":"همه را چک کن: دوباره برایش بخوان.","ex":"Let me check I've got that: ..."},{"en":"Numbers in pairs, dates with the month.","tr":"Sayıları ikişer ikişer, tarihleri ayın adıyla söyle.","fa":"عددها را دوتا‌دوتا بگو و تاریخ را با اسم ماه.","ex":"one-five, one-five; the third of March"}],"test":{"en":"Does the question start with did or do? Then the next verb has no -s and no -ed.","tr":"Soru did ya da do ile mi başlıyor? O zaman sonraki fiil -s ya da -ed almaz.","fa":"سؤال با ⁨did⁩ یا ⁨do⁩ شروع شده؟ پس فعل بعدی نه ⁨-s⁩ می‌گیرد و نه ⁨-ed⁩."},"contrast":{"en":"Turkish asks with the particle mi and Persian with intonation or 'aya', so the verb never changes. English moves did or do to the front and strips the main verb.","tr":"Türkçede soru 'mi' ekiyle yapılır ve fiil değişmez: 'On beş mi dedin?'. İngilizcede did ya da do başa gelir ve asıl fiil yalın kalır: Did you say...?","fa":"در فارسی سؤال را با لحن یا «آیا» می‌سازیم و فعل عوض نمی‌شود: «گفتی پونزده؟». در انگلیسی did یا do اول جمله می‌آید و فعل اصلی ساده می‌شود: «⁨Did you say...?⁩»"}},"errorWatch":[{"find":["did you said","did he said","did she said","did they said","did you sent","did you called","did you meant","did you received"],"fix":{"en":"After did, use the base verb: 'Did you say fifteen or fifty?'","tr":"did'den sonra yalın fiil kullan: 'Did you say fifteen or fifty?'","fa":"بعد از did فعل ساده بیاور: «⁨Did you say fifteen or fifty?⁩»"}},{"find":["does he works","does she works","does it works","do you can","does he has","does she has"],"fix":{"en":"After do or does, the verb has no -s: 'Does he work...?', 'Does she have...?'","tr":"do ya da does'tan sonra fiil -s almaz: 'Does he work...?', 'Does she have...?'","fa":"بعد از ⁨do⁩ یا ⁨does⁩ فعل ⁨-s⁩ نمی‌گیرد: «⁨Does he work...?⁩» و «⁨Does she have...?⁩»"}}]},"b2":{"id":"c-hr-1-3-b2","level":"B2","track":"B2","course":"hr","unit":"hr-1-3","title":"Guessing on the phone: must, can't, might","titleTr":"Telefonda tahmin: must, can't, might","exp":{"en":"On calls you often guess from clues: a busy line, a silence, no reply. B2 speakers use modal verbs of deduction. For the present: must = I'm almost sure it's true (\"The line is busy, so she must be on another call.\"), might/could = maybe, can't = I'm almost sure it's not true (\"That can't be his number: it has only nine digits.\"). For the past, add have + past participle: \"He can't have heard my message, or he would have called back.\", \"She might have sent it to the old address.\" Do not use can for a present guess (\"she can be on another call\" is not a guess in English), and never put to after a modal (\"must to be\").","tr":"Telefonda sık sık ipuçlarından tahmin yaparsın: meşgul hat, sessizlik, cevap yok. B2 seviyesinde konuşanlar çıkarım bildiren modal fiiller kullanır. Şimdiki zaman için: must = neredeyse eminim, doğru (\"The line is busy, so she must be on another call.\"), might/could = belki, can't = neredeyse eminim, doğru değil (\"That can't be his number: it has only nine digits.\"). Geçmiş için have + past participle ekle: \"He can't have heard my message, or he would have called back.\", \"She might have sent it to the old address.\" Türkçedeki \"-mış olmalı\" ve \"olamaz\" yapılarına benzer. Şimdiki tahmin için can kullanma (\"she can be on another call\" İngilizcede tahmin değildir) ve modal fiilden sonra asla to koyma (\"must to be\").","fa":"پشت تلفن اغلب از روی نشانه‌ها حدس می‌زنیم: خط اشغال است، کسی جواب نمی‌دهد، سکوت است. در سطح B2 برای این حدس‌ها از فعل‌های وجهی استنتاج (modals of deduction) استفاده می‌شود. برای زمان حال: must یعنی «تقریباً مطمئنم که درست است» («⁨The line is busy, so she must be on another call.⁩»)؛ might یا could یعنی «شاید»؛ can't یعنی «تقریباً مطمئنم که درست نیست» («⁨That can't be his number: it has only nine digits.⁩»). برای گذشته، بعد از فعل وجهی have + اسم مفعول (past participle) بیاور: «⁨He can't have heard my message, or he would have called back.⁩» و «⁨She might have sent it to the old address.⁩» معنایشان نزدیک به «حتماً نشنیده» و «شاید فرستاده باشد» در فارسی است. دو نکته: برای حدس درباره‌ی حال از can استفاده نکن («she can be on another call» در انگلیسی معنی حدس نمی‌دهد)، و هیچ‌وقت بعد از فعل وجهی to نگذار (نه «must to be»)."},"formsTable":{"headers":{"en":["How sure?","Present","Past"],"tr":["Ne kadar emin?","Şimdi","Geçmiş"],"fa":["چقدر مطمئنی؟","حال","گذشته"]},"rows":[["Almost sure: yes","She must be on another call.","He must have left early."],["Maybe","It might be the old number.","She might have sent it already."],["Almost sure: no","That can't be his number.","He can't have heard my message."]]},"wrong":"He can't heard my message.","right":"He can't have heard my message.","blank":{"sentence":"He can't ___ my message, or he would have called back.","word":"have heard","distractors":["heard","be heard"]},"wrong2":"The line is busy, so she must to be on another call.","right2":"The line is busy, so she must be on another call.","blank2":{"sentence":"The line is busy, so she ___ be on another call.","word":"must","distractors":["can","must to"]},"useIn":{"en":"B2 track: when you return the call, use one guess with must, might or can't (for example \"You must be driving, shall I call later?\").","tr":"B2 yolu: geri ararken must, might veya can't ile bir tahmin kullan (örneğin \"You must be driving, shall I call later?\").","fa":"مسیر B2: وقتی دوباره تماس می‌گیری، یک حدس با must، might یا can't بزن (مثلاً «⁨You must be driving, shall I call later?⁩»)."},"exitItem":{"from":"hr-1-3","kind":"blank","prompt":"Deniz ___ the wrong number; my phone shows no missed calls.","options":["must have dialled","can't have dialled","must dial"],"correct":0,"why":{"en":"must have dialled: a sure guess about the past, based on the evidence (no missed calls). 'Can't have dialled' says the opposite, and 'must dial' is about now.","tr":"must have dialled: kanıta (cevapsız arama yok) dayanan, geçmişle ilgili emin bir tahmin. 'Can't have dialled' tersini söyler; 'must dial' şimdiyle ilgilidir.","fa":"must have dialled درست است، چون حدس مطمئن درباره‌ی گذشته بر پایه‌ی شواهد است (تماس از دست رفته‌ای نیست). can't have dialled برعکس را می‌گوید و must dial درباره‌ی الان است."}},"expParts":{"hook":{"en":"No answer, a busy line, a silence. Good callers guess from the clues, and say how sure they are.","tr":"Cevap yok, hat meşgul, sessizlik. İyi arayanlar ipuçlarından tahmin yürütür ve ne kadar emin olduklarını söyler.","fa":"جواب نمی‌دهد، خط اشغال است، سکوت. آدم‌های باتجربه از روی نشانه‌ها حدس می‌زنند و می‌گویند چقدر مطمئن‌اند."},"tryWhy":{"en":"must: almost sure it is true. 'can' is not a guess in English, and a modal never takes to.","tr":"must: doğru olduğundan neredeyse eminsin. İngilizcede 'can' tahmin bildirmez ve modal fiil asla to almaz.","fa":"جواب must است، چون تقریباً مطمئنی که درست است. در انگلیسی can برای حدس به کار نمی‌رود و فعل وجهی هرگز to نمی‌گیرد."},"rule":[{"en":"Almost sure yes: must + verb.","tr":"Neredeyse eminim, evet: must + fiil.","fa":"اگر تقریباً مطمئنی که بله، must و فعل ساده را به کار ببر.","ex":"She must be on another call."},{"en":"Maybe: might or could + verb.","tr":"Belki: might ya da could + fiil.","fa":"اگر فقط احتمال می‌دهی، might یا could و فعل ساده را به کار ببر.","ex":"He might be on the bus."},{"en":"Almost sure no: can't + verb.","tr":"Neredeyse eminim, hayır: can't + fiil.","fa":"اگر تقریباً مطمئنی که نه، can't و فعل ساده را به کار ببر.","ex":"That can't be his number."},{"en":"About the past: add have + past participle.","tr":"Geçmiş için: have + past participle ekle.","fa":"برای حدس درباره‌ی گذشته، have و اسم مفعول را اضافه کن.","ex":"He can't have heard my message."}],"test":{"en":"Guessing about the past? Look for have after the modal. No have? Add it.","tr":"Geçmiş hakkında mı tahmin ediyorsun? Modalın ardından have var mı bak. Yoksa ekle.","fa":"درباره‌ی گذشته حدس می‌زنی؟ دنبال have بعد از فعل وجهی بگرد. اگر نیست، اضافه‌اش کن."},"contrast":{"en":"Turkish adds -mış olmalı ('duymamış olmalı') and Persian uses 'hatman' or 'shayad', so the verb changes, not a helper. In English the modal stays and have + past participle carries the past.","tr":"Türkçede tahmin fiilin ekinde: 'mesajımı duymamış olmalı'. İngilizcede modal sabit kalır, geçmişi have + past participle taşır: He can't have heard my message.","fa":"در فارسی حدس را با «حتماً» یا «شاید» و خود فعل می‌گوییم: «حتماً پیامم را نشنیده». در انگلیسی فعل وجهی ثابت می‌ماند و گذشته را have و اسم مفعول نشان می‌دهد: «He can't have heard my message.»"}},"errorWatch":[{"find":["must to","might to","can't to","cannot to","could to be"],"fix":{"en":"A modal verb never takes to: 'She must be on another call.'","tr":"Modal fiil asla to almaz: 'She must be on another call.'","fa":"فعل وجهی هرگز to نمی‌گیرد: «⁨She must be on another call.⁩»"}},{"find":["can't heard","can't received","can't saw","must forgot","might sent","must saw"],"fix":{"en":"For a past guess use modal + have + past participle: 'He can't have heard my message.'","tr":"Geçmişle ilgili tahminde modal + have + past participle kullan: 'He can't have heard my message.'","fa":"برای حدس درباره‌ی گذشته، بعد از فعل وجهی have و اسم مفعول بیاور: «He can't have heard my message.»"}}]},"vocab":{"id":"c-hr-1-3-v","level":"B1","category":"vocab","course":"hr","unit":"hr-1-3","goals":["career"],"title":{"en":"On the Phone","tr":"Telefonda","fa":"پشت تلفن"},"cards":[{"word":"voicemail","sentence":"He left a voicemail at 8 a.m.","meaning":{"en":"A recorded phone message.","tr":"sesli mesaj.","fa":"پیام صوتی؛ پیغام‌گیر"}},{"word":"return a call","sentence":"I'll return your call this afternoon.","gap":"return your call","accept":["return your call","return a call"],"meaning":{"en":"To phone someone back.","tr":"geri aramak.","fa":"دوباره به کسی زنگ زدن؛ در جواب تماسش با او تماس گرفتن"}},{"word":"repeat","sentence":"Sorry, could you repeat that?","meaning":{"en":"To say something again.","tr":"tekrar etmek.","fa":"تکرار کردن"}},{"word":"spell","sentence":"How do you spell your surname?","meaning":{"en":"To say the letters of a word one by one.","tr":"hecelemek.","fa":"هجی کردن"}},{"word":"speak up","sentence":"Could you speak up? The line is bad.","meaning":{"en":"To speak more loudly.","tr":"daha yüksek sesle konuşmak.","fa":"بلندتر حرف زدن"}},{"word":"the line is breaking up","sentence":"Sorry, the line is breaking up.","meaning":{"en":"The sound keeps cutting off.","tr":"hat kesiliyor.","fa":"صدا قطع و وصل می‌شود؛ خط خوب نیست"}},{"word":"hold on","sentence":"Hold on, I'll get a pen.","meaning":{"en":"Wait a moment.","tr":"bir dakika bekle.","fa":"یک لحظه گوشی؛ لطفاً صبر کن"}},{"word":"get back to you","sentence":"I'll get back to you by 4 p.m.","meaning":{"en":"To contact you again with an answer.","tr":"sana dönüş yapmak.","fa":"بعداً خبر دادن؛ با جواب دوباره تماس گرفتن"}},{"word":"digit","sentence":"Your phone number has eleven digits.","gap":"digits","accept":["digits","digit"],"meaning":{"en":"A single number, 0 to 9.","tr":"rakam.","fa":"رقم (یک عدد از ۰ تا ۹)"}},{"word":"surname","sentence":"Could you spell your surname?","meaning":{"en":"Family name.","tr":"soyadı.","fa":"نام خانوادگی"}}]},"story":{"id":"c-hr-1-3-s","level":"B1","genre":"Workplace","course":"hr","unit":"hr-1-3","title":{"en":"The Voicemail","tr":"Sesli Mesaj","fa":"پیام صوتی"},"text":"At 8:05, Leyla's phone showed a missed call and a voicemail. She pressed play. A man spoke fast, with a lot of traffic behind him.\n\n\"Hello, this is... Deniz Aydin, A-Y-D-I-N, calling about the driver job. My number is zero-five-three-two, one-five-five, zero-nine, nine-nine... please call me after five.\"\n\nShe played it twice. The number was either 155 or 550. She could not tell. If she guessed wrong, a good candidate would think no one wanted him.\n\nShe took a breath and called the number she thought was right.\n\n\"Hello?\" said a woman.\n\n\"Sorry, I think I have the wrong number. I'm looking for Deniz Aydin.\"\n\n\"Wrong number,\" said the woman, kindly, and hung up.\n\nLeyla tried the second version. This time a tired voice answered. \"Yes?\"\n\n\"Hello, is this Deniz Aydin? This is Leyla from Atlas Logistics. Sorry, the voicemail was not clear. Did you say your number is one-five-five or five-five-zero? And could you spell your surname for me?\"\n\nHe laughed. \"A-Y-D-I-N. And sorry, I was on a bus. Everybody on the bus was looking at me.\"\n\n\"Let me check I've got that,\" Leyla said, and read the number back, digit by digit. He said yes. She wrote it in the system, twice.","vocab":[{"word":"missed call","en":"A call you did not answer.","tr":"cevapsız arama","fa":"تماس بی‌پاسخ"},{"word":"traffic","en":"Cars and noise on the road.","tr":"trafik","fa":"ترافیک"},{"word":"guess","en":"To say something without being sure.","tr":"tahmin etmek","fa":"حدس زدن"},{"word":"hang up","en":"To end a phone call.","tr":"telefonu kapatmak","fa":"گوشی را گذاشتن؛ تماس را قطع کردن"},{"word":"read back","en":"To say what you wrote so the other person can check.","tr":"okuyarak teyit etmek","fa":"بازخوانی؛ خواندن دوباره‌ی یادداشت برای تأیید طرف مقابل"}],"quiz":[{"prompt":"What was Leyla's problem with the voicemail?","options":["She could not tell two numbers apart","Deniz did not leave a name","The message was in Turkish"],"correct":0},{"prompt":"Choose the correct question.","options":["Did you said 155 or 550?","Did you say 155 or 550?","You did say 155 or 550?"],"correct":1},{"prompt":"Why did Leyla read the number back?","options":["To check she had it right","Because she was bored","To practise her English"],"correct":0},{"prompt":"How might the woman with the wrong number feel at the end?","options":["A little confused, but not angry","Very angry","Interested in the job"],"correct":0}],"notice":{"en":"Deniz's voicemail has one number Leyla cannot hear clearly. Watch how she checks it without making him feel bad.","tr":"Deniz'in sesli mesajında Leyla'nın net duyamadığı bir sayı var. Onu kötü hissettirmeden nasıl kontrol ettiğine dikkat et.","fa":"در پیام صوتی دنیز عددی هست که لیلا خوب نمی‌شنود. دقت کن چطور بدون اینکه دنیز احساس بدی پیدا کند، آن را چک می‌کند."},"bridge":{"en":"'Did you say...?' and 'Could you spell...?' saved the call. Next: see how checking questions work.","tr":"'Did you say...?' ve 'Could you spell...?' görüşmeyi kurtardı. Sırada: kontrol sorularının nasıl çalıştığını gör.","fa":"«⁨Did you say...?⁩» و «⁨Could you spell...?⁩» تماس را نجات دادند. قدم بعد: ببین سؤال‌های چک‌کردنی چطور ساخته می‌شوند."}},"speaking":{"id":"hr-1-3","course":"hr","unit":"hr-1-3","topic":{"en":"Returning a Call and Checking Details","tr":"Geri Arama ve Bilgi Teyidi","fa":"تماس گرفتن دوباره و تأیید جزئیات"},"warmup":{"en":"Say your phone number and your surname spelling out loud. How many times did you stumble?","tr":"Telefon numaranı ve soyadının hecelenişini yüksek sesle söyle. Kaç kez tıkandın?","fa":"شماره‌ی تلفن خودت را بلند بگو و نام خانوادگی‌ات را هجی کن. چند بار مکث کردی یا گیر کردی؟"},"questions":[{"en":"Call a candidate back. Ask them to spell their name and repeat their number.","tr":"Bir adayı geri ara. İsmini hecelemesini ve numarasını tekrar etmesini iste.","fa":"به متقاضی‌ای که زنگ زده بود دوباره زنگ بزن. از او بخواه نامش را هجی کند و شماره‌اش را تکرار کند."},{"en":"Confirm an interview time: the date, the hour and the address.","tr":"Bir mülakat zamanını teyit et: tarih, saat ve adres.","fa":"زمان یک مصاحبه را تأیید کن: تاریخ، ساعت و نشانی."},{"en":"The line is bad. Ask the other person to speak up and repeat the last part.","tr":"Hat kötü. Karşıdakinden daha yüksek sesle konuşmasını ve son kısmı tekrarlamasını iste.","fa":"صدا خوب نمی‌رسد. از طرف مقابل بخواه بلندتر صحبت کند و قسمت آخر را تکرار کند."}],"followups":[{"en":"Read the number back digit by digit and finish with: \"Did I get that right?\"","tr":"Numarayı rakam rakam geri oku ve şununla bitir: \"Did I get that right?\"","fa":"شماره را رقم‌به‌رقم بازخوانی کن و در آخر بپرس: «⁨Did I get that right?⁩»"},{"en":"Now spell your own name and read your own number back, slowly.","tr":"Şimdi kendi adını kodla ve kendi numaranı yavaşça tekrar oku.","fa":"حالا اسم خودت را هجی کن و شماره‌ی خودت را آرام بازخوانی کن."}],"expressions":[{"phrase":"Sorry, could you repeat that?","meaning":{"en":"Asks for a repeat politely.","tr":"Kibarca tekrar ister.","fa":"مؤدبانه تکرار را درخواست می‌کند."}},{"phrase":"Did you say fifteen or fifty?","meaning":{"en":"Checks two similar numbers.","tr":"İki benzer sayıyı kontrol eder.","fa":"دو عددِ شبیه به هم را چک می‌کند."}},{"phrase":"Let me check I've got that.","meaning":{"en":"Introduces a read-back.","tr":"Geri okumayı başlatır.","fa":"بازخوانی اطلاعات را شروع می‌کند."}}],"culture":{"en":"Asking someone to repeat or spell is normal and professional on international calls. It shows care, not weakness. Many native speakers also ask for repeats on bad lines.","tr":"Uluslararası görüşmelerde tekrar ya da hecelemek istemek normal ve profesyoneldir. Zayıflık değil, özen göstergesidir. Ana dili İngilizce olanlar da kötü hatlarda tekrar ister.","fa":"در تماس‌های بین‌المللی، اینکه از کسی بخواهی حرفش را تکرار یا اسمش را هجی کند، کاملاً عادی و حرفه‌ای است. این کار نشانه‌ی دقت است، نه ضعف زبان. خود انگلیسی‌زبان‌ها هم وقتی خط بد است دوباره می‌پرسند."},"model":"Hello, is this Deniz Aydin? This is Leyla from Atlas Logistics, returning your call. Sorry, the line was not clear. Could you spell your surname for me? Thank you. And did you say one-five-five or five-five-zero? Let me check I've got that: zero-five-three-two, one-five-five, zero-nine, nine-nine. Your interview is on Thursday the twelfth of March at ten. Did I get that right?","selfCheck":[{"en":"I asked the person to spell their name.","tr":"Kişiden adını hecelemesini istedim.","fa":"از طرف خواستم اسمش را هجی کند."},{"en":"I used 'Did you say...?' with the base verb.","tr":"'Did you say...?' kalıbını yalın fiille kullandım.","fa":"«⁨Did you say...?⁩» را با فعل ساده به کار بردم."},{"en":"I read the number back in pairs or digit by digit.","tr":"Numarayı ikişer ikişer ya da rakam rakam geri okudum.","fa":"شماره را دوتا‌دوتا یا رقم‌به‌رقم دوباره خواندم."},{"en":"I gave the date with the month and asked 'Did I get that right?'","tr":"Tarihi ayın adıyla söyledim ve 'Did I get that right?' diye sordum.","fa":"تاریخ را با اسم ماه گفتم و پرسیدم «⁨Did I get that right?⁩»"}]},"writing":{"id":"c-hr-1-3-w","title":{"en":"A confirmation message to Deniz","tr":"Deniz'e teyit mesajı","fa":"پیام تأیید برای دنیز"},"course":"hr","unit":"hr-1-3","type":"writing","difficulty":"easy","prompt":{"en":"After the call, write a 3-line confirmation message to Deniz: his full name, the phone number you have and the interview day. Ask him to reply \"confirmed\".","tr":"Görüşmeden sonra Deniz'e 3 satırlık bir teyit mesajı yaz: tam adı, elindeki telefon numarası ve mülakat günü. Ondan \"confirmed\" yazmasını iste.","fa":"بعد از تماس، یک پیام تأیید سه‌خطی برای دنیز بنویس: نام کامل او، شماره‌ای که از او داری و روز مصاحبه. از او بخواه در جواب بنویسد «confirmed»."},"model":"Hi Deniz, thank you for speaking with me today. I have your name as Deniz Aydin, your number as 0532 155 09 99 and your interview on Thursday 12 March at 10:00. I've attached a map of our office. Could you reply \"confirmed\" if this is correct? Kind regards, Leyla","frame":"Hi ___, thank you for ___. I have your name as ___, your number as ___ and your interview on ___. Could you reply \"confirmed\" if ___? Kind regards, ___","words":[{"word":"confirm"},{"word":"surname"},{"word":"could you"}],"minWords":35,"minSentences":3,"rubric":["Task done: name, number, day, request to reply","Organised: greeting, details, request, close","Language: Could you + base verb; dates and numbers correct","Tone: friendly and exact"],"rubricI18n":{"tr":["Görev: ad, numara, gün, yanıt ricası","Düzen: selamlama, ayrıntılar, rica, kapanış","Dil: Could you + yalın fiil; tarihler ve sayılar doğru","Üslup: samimi ve kesin"],"fa":["کامل بودن کار: نام، شماره، روز، درخواست پاسخ","نظم: سلام، جزئیات، درخواست، پایان","زبان: Could you با شکل ساده‌ی فعل؛ تاریخ‌ها و عددها درست","لحن: دوستانه و دقیق"]},"portfolio":null,"parts":[{"t":{"en":"His full name","tr":"Tam adı","fa":"اسم کاملش"},"find":["your name as","name as","surname","full name"],"sample":"Deniz Aydin"},{"t":{"en":"His phone number","tr":"Telefon numarası","fa":"شماره تلفنش"},"find":["your number","number as","phone"],"sample":"0532 155 09 99"},{"t":{"en":"The interview day and time","tr":"Görüşme günü ve saati","fa":"روز و ساعت مصاحبه"},"find":["interview on","monday","tuesday","wednesday","thursday","friday"],"sample":"Thursday 12 March, 10:00"},{"t":{"en":"A request to reply \"confirmed\"","tr":"\"confirmed\" diye cevap vermesi ricası","fa":"درخواست جواب «⁨confirmed⁩»"},"find":["reply","confirm","let me know"],"sample":"reply \"confirmed\" if all is correct"}]},"perspective":{"id":"c-hr-1-3-p","title":{"en":"Deniz on a noisy bus","tr":"Gürültülü otobüste Deniz","fa":"دنیز در اتوبوس شلوغ"},"course":"hr","unit":"hr-1-3","type":"perspective","minSentences":2,"prompt":{"en":"You are Deniz calling from a noisy bus. Write 2-3 sentences in first person: what makes it hard to be understood, and what would help?","tr":"Gürültülü bir otobüsten arayan Deniz'sin. Birinci tekil şahısla 2-3 cümle yaz: anlaşılmayı ne zorlaştırıyor ve ne yardımcı olur?","fa":"تو دنیز هستی و از داخل یک اتوبوس شلوغ و پرسروصدا تماس گرفته‌ای. از زبان خودت دو یا سه جمله بنویس: چه چیزی باعث می‌شود حرفت را نفهمند و چه چیزی کمک می‌کند؟"}},"exit":{"id":"c-hr-1-3-x","course":"hr","unit":"hr-1-3","type":"exit","items":[{"from":"hr-1-3","kind":"blank","prompt":"Sorry, did you ___ the 13th or the 30th?","options":["mean","meant","meaning"],"correct":0,"point":2,"why":{"en":"mean: after 'did you', use the plain verb. 'Meant' doubles the past, and 'meaning' isn't a verb form here.","tr":"mean: 'did you'dan sonra yalın fiil gelir. 'Meant' geçmişi iki kez söyler; 'meaning' burada fiil biçimi değildir.","fa":"mean درست است، چون بعد از did you فعل ساده می‌آید. meant گذشته را دو بار می‌گوید و meaning اینجا شکل فعل نیست."}},{"from":"hr-1-3","kind":"blank","prompt":"How ___ he spell his first name?","options":["do","does","is"],"correct":1,"point":2,"why":{"en":"does: 'he' takes does in a present simple question. 'Do' is for I, you, we, they, and 'is' would need -ing.","tr":"does: geniş zaman sorusunda 'he' does alır. 'Do' I, you, we, they içindir; 'is' -ing ister.","fa":"does درست است، چون در سؤال حال ساده he با does می‌آید. do برای I و you و we و they است و is فعل ing‌دار می‌خواهد."},"hint2":{"en":"Is the subject he, she or it? In a present simple question, the helping verb changes, not the main verb.","tr":"Özne he, she ya da it mi? Geniş zamanlı bir soruda değişen ana fiil değil, yardımcı fiildir.","fa":"فاعل ⁨he⁩، ⁨she⁩ یا ⁨it⁩ است؟ در سؤالِ زمان حال ساده، فعل کمکی عوض می‌شود، نه فعل اصلی."}},{"from":"hr-1-3","kind":"mcq","prompt":"Which sentence introduces a read-back?","options":["Let me check I've got that.","Hold on, I'm not sure.","The line is breaking up."],"correct":0,"point":3,"why":{"en":"'Let me check I've got that' tells the caller you will repeat the details back. The other two say there is a problem, not a check.","tr":"'Let me check I've got that' arayana bilgileri tekrar edeceğini söyler. Diğer ikisi bir kontrolü değil, bir sorunu anlatır.","fa":"«Let me check I've got that» به طرف می‌گوید جزئیات را برایش تکرار می‌کنی. دو جمله‌ی دیگر از یک مشکل می‌گویند، نه از بررسی."},"hint2":{"en":"A read-back repeats the details to check them. Which sentence says you are about to do that?","tr":"Geri okuma, bilgileri kontrol etmek için tekrarlamaktır. Hangi cümle bunu yapmak üzere olduğunu söylüyor?","fa":"بازخوانی یعنی تکرار جزئیات برای چک کردنشان. کدام جمله می‌گوید داری همین کار را می‌کنی؟"}},{"from":"hr-1-2","kind":"blank","prompt":"Could you ___ me the details by Monday?","options":["to send","sending","send"],"correct":2,"point":2,"why":{"en":"send: 'Could you' + plain verb. 'To send' and 'sending' don't follow could.","tr":"send: 'Could you' + yalın fiil. 'To send' ve 'sending' could'dan sonra gelmez.","fa":"send درست است، چون بعد از Could you فعل ساده می‌آید. to send و sending بعد از could نمی‌آیند."},"hint2":{"en":"Could you is like can or would: which verb form comes straight after it?","tr":"Could you, can ya da would gibidir: Hemen ardından fiilin hangi biçimi gelir?","fa":"⁨Could you⁩ مثل ⁨can⁩ یا ⁨would⁩ است: بلافاصله بعدش فعل با چه شکلی می‌آید؟"}},{"from":"hr-1-2","kind":"mcq","prompt":"Which line gives a reason AND a deadline?","options":["Could you reply by Friday, because the visa office closes early?","Could you reply by Friday, please?","Could you reply soon, because the visa office closes early?"],"correct":0,"point":1,"why":{"en":"It gives both a deadline (Friday) and a reason (the visa office). Each of the other two gives only one.","tr":"Hem bir son tarih (cuma) hem bir neden (vize ofisi) verir. Diğer ikisinin her biri yalnızca birini verir.","fa":"هم مهلت می‌دهد (جمعه) و هم دلیل (اداره‌ی ویزا). هر کدام از دو گزینه‌ی دیگر فقط یکی را دارند."}},{"from":"hr-1-1","kind":"blank","prompt":"Right now, Leyla ___ the voicemail again.","options":["plays","is playing","play"],"correct":1,"point":2,"why":{"en":"is playing: 'right now' is happening at this moment, so is + -ing. 'Plays' is a habit, and 'play' doesn't agree with Leyla.","tr":"is playing: 'right now' şu anda olandır, bu yüzden is + -ing. 'Plays' alışkanlıktır; 'play' Leyla ile uyuşmaz.","fa":"is playing درست است، چون right now یعنی همین لحظه و is و فعل ing‌دار لازم است. plays عادت است و play با Leyla جور نیست."}},{"from":"hr-1-3","kind":"mcq","prompt":"On a bad line you cannot tell if the room is \"fourteen\" or \"forty\". What do you do?","options":["Ask, then repeat it: \"Was that one-four?\"","Write 14: it is more likely","Wait and check the email later"],"correct":0,"why":{"en":"Ask, then repeat it: guessing is the real mistake. Repeat the detail so the other person can correct you.","tr":"Sor, sonra tekrarla: Asıl hata tahmin etmektir. Karşındakinin seni düzeltebilmesi için bilgiyi tekrarla.","fa":"بپرس و بعد تکرارش کن: اشتباه واقعی حدس زدن است. آن اطلاعات را تکرار کن تا طرف مقابل بتواند اصلاحت کند."},"point":1}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
